package android.content.res; import android.app.WindowConfiguration; public class Configuration { public WindowConfiguration windowConfiguration; public int uiMode,densityDpi=160,screenWidthDp,screenHeightDp,orientation; public Configuration(){} public Configuration(Configuration c){windowConfiguration=c.windowConfiguration;uiMode=c.uiMode;densityDpi=c.densityDpi;screenWidthDp=c.screenWidthDp;screenHeightDp=c.screenHeightDp;orientation=c.orientation;} }
